import re

def parse_dialog(dialog_text, company_id):
    """Parse dialog into customer and agent messages"""
    messages = dialog_text.split('\n\n')
    customer_msgs = []
    agent_msgs = []
    for msg in messages:
        if msg.strip().startswith(company_id):
            agent_msgs.append(msg)
        else:
            customer_msgs.append(msg)
    return customer_msgs, agent_msgs

def has_apology_in_agent_msgs(agent_msgs):
    """Check if agent apologizes in any message"""
    apology_patterns = ['sorry', 'apologize', 'apologies', 'apology', 'apologise']
    for msg in agent_msgs:
        msg_lower = msg.lower()
        for pattern in apology_patterns:
            if pattern in msg_lower:
                return True
    return False

