# Let me try a stricter complaint definition and broader apology definition

def has_strict_complaint(customer_msgs):
    """Very strict: only explicit complaint/dissatisfaction expressions"""
    complaint_patterns = [
        'complaint', 'terrible', 'horrible', 'worst', 'poor service', 
        'unacceptable', 'disappointed', 'disgusting', 'outrageous', 
        'shameful', 'pathetic', 'incompetent', 'awful', 'ridiculous',
        'appalling', 'disgraceful', 'furious', 'livid'
    ]
    for msg in customer_msgs:
        msg_lower = msg.lower()
        for pattern in complaint_patterns:
            if pattern in msg_lower:
                return True
    return False

def has_broad_apology(agent_msgs):
    """Broader: includes various forms of acknowledging issues"""
    apology_patterns = ['sorry', 'apologize', 'apologies', 'apology', 'apologise',
                       'regret', 'understand your frustration', 'understand your concern',
                       'sincerely', 'inconvenience']
    for msg in agent_msgs:
        msg_lower = msg.lower()
        for pattern in apology_patterns:
            if pattern in msg_lower:
                return True
    return False

